import React from 'react';
import Header from '../components/ui/Header';
import { Download, Share2 } from 'lucide-react';

const AgentMarketplace = () => {
  const handleExport = () => {
    // Generate a dummy JSON representing the canvas state
    const canvasState = {
      nodes: [
        { id: '1', type: 'llm', data: { prompt: 'Analyze this data' } }
      ],
      edges: []
    };
    const blob = new Blob([JSON.stringify(canvasState, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'agent_playbook.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white overflow-hidden selection:bg-green-500/30">
      <Header />
      
      <main className="pt-32 pb-20 px-8 max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-end mb-12 border-b border-white/10 pb-8">
          <div>
            <h1 className="text-5xl font-bold tracking-tight mb-4">Agent Marketplace</h1>
            <p className="text-xl text-gray-400 font-light">Discover, export, and deploy enterprise-grade cognitive playbooks.</p>
          </div>
          <div className="mt-6 md:mt-0 flex gap-4">
            <button 
              onClick={handleExport}
              className="px-6 py-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl flex items-center gap-2 transition-colors"
            >
              <Download size={18} />
              <span>Export Current Playbook</span>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Dummy Playbook Cards */}
          {[1, 2, 3].map((item) => (
            <div key={item} className="p-6 rounded-2xl bg-white/5 border border-white/10 hover:border-green-500/50 transition-colors group cursor-pointer">
              <div className="h-40 bg-gradient-to-br from-green-500/20 to-blue-500/20 rounded-xl mb-6 relative overflow-hidden">
                <div className="absolute inset-0 bg-[url('/noise.png')] opacity-20 mix-blend-overlay"></div>
              </div>
              <h3 className="text-2xl font-semibold mb-2">Automated Legal Analyst</h3>
              <p className="text-gray-400 text-sm mb-6">Processes 100+ PDFs for compliance mapping automatically.</p>
              
              <div className="flex justify-between items-center">
                <span className="text-green-400 text-sm font-medium">Enterprise Tier</span>
                <button className="text-gray-400 hover:text-white transition-colors">
                  <Share2 size={18} />
                </button>
              </div>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
};

export default AgentMarketplace;
